import csv
import io
import json

FIELDS = ("id", "name")


def _normalize_row(row):
    normalized = {}
    for key in FIELDS:
        value = row.get(key)
        normalized[key] = "" if value is None else str(value)
    return normalized


def _normalize_rows(rows):
    return [_normalize_row(row) for row in rows]


def _serialize_csv(rows):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(FIELDS)
    for row in rows:
        writer.writerow([row[key] for key in FIELDS])
    return buffer.getvalue()


def _serialize_json(rows):
    return json.dumps(rows, ensure_ascii=False, separators=(",", ":"))


def export_rows(rows, format):
    if format == "csv":
        return _serialize_csv(_normalize_rows(rows))
    if format == "json":
        return _serialize_json(_normalize_rows(rows))
    raise ValueError("unsupported format")

